#[summary("Task functions: clamp limits an i64 to a closed range [lo, hi].")]
mod tasks {
    #[effects(pure)]
    #[uses(clamp_result, ordered)]
    fn clamp(x: i64, lo: i64, hi: i64) -> (r: i64)
        requires ordered(lo, hi),
        ensures clamp_result(x, lo, hi, r),
    {
        if x < lo {
            lo
        } else if x > hi {
            hi
        } else {
            x
        }
    }

    spec fn clamp_result(x: i64, lo: i64, hi: i64, r: i64) -> bool {
        if x < lo {
            r == lo
        } else if x > hi {
            r == hi
        } else {
            r == x
        }
    }

    spec fn ordered(lo: i64, hi: i64) -> bool {
        lo <= hi
    }
}

#[summary("Exact floor midpoint of two i64 values, floor((a+b)/2) without overflow.")]
mod tasks {
    #[effects(pure)]
    #[uses(half_floor_ok)]
    fn half_floor(x: i64) -> (h: i64)
        ensures half_floor_ok(x, h),
    {
        let c: i64 = x / 2;
        if x >= 0 {
            c
        } else if c * 2 == x {
            c
        } else {
            c - 1
        }
    }

    spec fn half_floor_ok(x: i64, h: i64) -> bool {
        2 * h <= x && x < 2 * h + 2
    }

    #[effects(pure)]
    #[uses(half_floor_ok, midpoint_ok)]
    fn midpoint(a: i64, b: i64) -> (r: i64)
        ensures midpoint_ok(a, b, r),
    {
        let fa: i64 = half_floor(a);
        let fb: i64 = half_floor(b);
        let ra: i64 = a - 2 * fa;
        let rb: i64 = b - 2 * fb;
        if ra == 1 && rb == 1 {
            fa + fb + 1
        } else {
            fa + fb
        }
    }

    spec fn midpoint_ok(a: i64, b: i64, r: i64) -> bool {
        2 * r <= a + b && a + b < 2 * r + 2
    }
}

#[summary("Saturating left-to-right sum of an i64 slice")]
mod tasks {
    #[uses(sat_fold)]
    spec fn fold_is(a: &[i64], n: usize, acc: i64) -> bool {
        acc == sat_fold(a, n)
    }

    #[effects(pure)]
    #[uses(sat_add_post, sat_add_spec)]
    fn sat_add(acc: i64, x: i64) -> (r: i64)
        ensures sat_add_post(acc, x, r),
    {
        if x >= 0 {
            if acc > i64::MAX - x {
                i64::MAX
            } else {
                acc + x
            }
        } else {
            if acc < i64::MIN - x {
                i64::MIN
            } else {
                acc + x
            }
        }
    }

    #[uses(sat_add_spec)]
    spec fn sat_add_post(acc: i64, x: i64, r: i64) -> bool {
        r == sat_add_spec(acc, x)
    }

    spec fn sat_add_spec(acc: i64, x: i64) -> i64 {
        if x >= 0 {
            if acc > i64::MAX - x {
                i64::MAX
            } else {
                acc + x
            }
        } else {
            if acc < i64::MIN - x {
                i64::MIN
            } else {
                acc + x
            }
        }
    }

    #[uses(sat_add_spec)]
    spec fn sat_fold(a: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else if n > a.len() {
            0
        } else {
            sat_add_spec(sat_fold(a, n - 1), a[n - 1])
        }
    }

    #[effects(pure)]
    #[uses(fold_is, sat_add_post, sat_add_spec, sat_fold)]
    fn sat_sum(a: &[i64]) -> (r: i64)
        ensures fold_is(a, a.len(), r),
    {
        let mut acc: i64 = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant i <= a.len(), fold_is(a, i, acc),
            decreases a.len() - i,
        {
            acc = sat_add(acc, a[i]);
            i = i + 1;
        }
        acc
    }
}

#[summary("Counting helpers: count elements of a slice lying in an inclusive range")]
mod tasks {
    #[effects(pure)]
    #[uses(count_prefix, result_is_count)]
    fn count_in_range(a: &[i64], lo: i64, hi: i64) -> (r: usize)
        ensures result_is_count(a, lo, hi, r),
    {
        let mut i: usize = 0;
        let mut c: usize = 0;
        while i < a.len()
            invariant i <= a.len(), c <= i, c == count_prefix(a, lo, hi, i),
            decreases a.len() - i,
        {
            if lo <= a[i] && a[i] <= hi {
                c = c + 1;
            }
            i = i + 1;
        }
        c
    }

    spec fn count_prefix(a: &[i64], lo: i64, hi: i64, n: usize) -> usize
        decreases n,
    {
        if n == 0 {
            0
        } else if n > a.len() {
            0
        } else {
            count_prefix(a, lo, hi, n - 1) + (if lo <= a[n - 1] && a[n - 1] <= hi { 1 } else { 0 })
        }
    }

    spec fn result_is_count(a: &[i64], lo: i64, hi: i64, r: usize) -> bool {
        r == count_prefix(a, lo, hi, a.len())
    }
}

#[summary("Task implementations: first index of the maximum of a non-empty i64 slice.")]
mod tasks {
    #[effects(pure)]
    #[uses(is_max_index, no_earlier_max, non_empty, scan_inv_bound, scan_inv_first, scan_inv_max)]
    fn first_max_index(a: &[i64]) -> (r: usize)
        requires non_empty(a),
        ensures is_max_index(a, r), no_earlier_max(a, r),
    {
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant scan_inv_bound(a, best, i), scan_inv_max(a, best, i), scan_inv_first(a, best),
            decreases a.len() - i,
        {
            if a[i] > a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn is_max_index(a: &[i64], m: usize) -> bool {
        m < a.len() && (forall|j: usize| j < a.len() ==> #[trigger] a[j] <= a[m])
    }

    spec fn no_earlier_max(a: &[i64], m: usize) -> bool {
        m < a.len() && (forall|j: usize| j < m ==> #[trigger] a[j] < a[m])
    }

    spec fn non_empty(a: &[i64]) -> bool {
        a.len() > 0
    }

    spec fn scan_inv_bound(a: &[i64], best: usize, i: usize) -> bool {
        best < i && i <= a.len()
    }

    spec fn scan_inv_first(a: &[i64], best: usize) -> bool {
        forall|j: usize| j < best ==> #[trigger] a[j] < a[best]
    }

    spec fn scan_inv_max(a: &[i64], best: usize, i: usize) -> bool {
        forall|j: usize| j < i ==> #[trigger] a[j] <= a[best]
    }
}

#[summary("Task implementations: last index of the minimum of a non-empty i64 slice")]
mod tasks {
    spec fn is_last_min(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|p1: usize| p1 < a.len() ==> #[trigger] a[p1] >= a[r]) && (forall|p2: usize| r < p2 && p2 < a.len() ==> #[trigger] a[p2] > a[r])
    }

    #[effects(pure)]
    #[uses(is_last_min, nonempty, scan_ok)]
    fn last_min_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures is_last_min(a, r),
    {
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant scan_ok(a, i, best),
            decreases a.len() - i,
        {
            if a[i] <= a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }

    spec fn scan_ok(a: &[i64], i: usize, best: usize) -> bool {
        best < i && i <= a.len() && (forall|q1: usize| q1 < i ==> #[trigger] a[q1] >= a[best]) && (forall|q2: usize| best < q2 && q2 < i ==> #[trigger] a[q2] > a[best])
    }
}

#[summary("Task functions: strictly_increasing check on i64 slices")]
mod tasks {
    #[uses(prefix_ok)]
    spec fn is_strictly_increasing(a: &[i64]) -> bool {
        prefix_ok(a, a.len())
    }

    #[uses(prefix_ok, within_len)]
    spec fn loop_inv(a: &[i64], i: usize, ok: bool) -> bool {
        within_len(a, i) && ok == prefix_ok(a, i)
    }

    #[uses(pair_ok)]
    spec fn pair_ok(a: &[i64], j: usize) -> bool {
        j + 1 < a.len() ==> a[j] < a[j + 1]
    }

    #[uses(pair_ok)]
    spec fn prefix_ok(a: &[i64], i: usize) -> bool {
        forall|j: usize| j < i ==> #[trigger] pair_ok(a, j)
    }

    #[uses(is_strictly_increasing)]
    spec fn result_matches(a: &[i64], r: bool) -> bool {
        r == is_strictly_increasing(a)
    }

    #[effects(pure)]
    #[uses(is_strictly_increasing, loop_inv, pair_ok, prefix_ok, result_matches, within_len)]
    fn strictly_increasing(a: &[i64]) -> (r: bool)
        ensures result_matches(a, r),
    {
        let mut i: usize = 0;
        let mut ok: bool = true;
        while i + 1 < a.len()
            invariant loop_inv(a, i, ok),
            decreases a.len() - i,
        {
            if !(a[i] < a[i + 1]) {
                ok = false;
            }
            i = i + 1;
        }
        ok
    }

    spec fn within_len(a: &[i64], i: usize) -> bool {
        i <= a.len()
    }
}

#[summary("Binary search: lower_bound over a sorted i64 slice")]
mod tasks {
    spec fn at_or_above(a: &[i64], t: i64, k: usize) -> bool {
        forall|i: usize| k <= i && i < a.len() ==> #[trigger] a[i] >= t
    }

    spec fn below(a: &[i64], t: i64, k: usize) -> bool {
        forall|i: usize| i < k && i < a.len() ==> #[trigger] a[i] < t
    }

    spec fn is_sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i < j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }

    spec fn lb_inv(a: &[i64], t: i64, lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len() && below(a, t, lo) && at_or_above(a, t, hi)
    }

    spec fn lb_result(a: &[i64], t: i64, r: usize) -> bool {
        r <= a.len() && below(a, t, r) && (r < a.len() ==> a[r] >= t)
    }

    #[effects(pure)]
    #[uses(at_or_above, below, is_sorted, lb_inv, lb_result)]
    fn lower_bound(a: &[i64], t: i64) -> (r: usize)
        requires is_sorted(a),
        ensures lb_result(a, t, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = a.len();
        while lo < hi
            invariant lb_inv(a, t, lo, hi), is_sorted(a),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if a[mid] < t {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        lo
    }
}

#[summary("Integer task implementations, starting with floor division.")]
mod tasks {
    #[effects(pure)]
    #[uses(div_floor_post, div_floor_pre)]
    fn div_floor(a: i64, b: i64) -> (r: i64)
        requires div_floor_pre(a, b),
        ensures div_floor_post(a, b, r),
    {
        let q: i64 = a / b;
        let m: i64 = a % b;
        if m != 0 && (m < 0 && b > 0 || m > 0 && b < 0) {
            q - 1
        } else {
            q
        }
    }

    spec fn div_floor_post(a: i64, b: i64, r: i64) -> bool {
        (b > 0 ==> r * b <= a && a < (r + 1) * b) && (b < 0 ==> r * b >= a && a > (r + 1) * b)
    }

    spec fn div_floor_pre(a: i64, b: i64) -> bool {
        b != 0 && !(a == i64::MIN && b == -1)
    }
}

#[summary("Task implementations: floor-division remainder mod_floor.")]
mod tasks {
    spec fn abs_of(x: i64) -> i64 {
        if x < 0 {
            0 - x
        } else {
            x
        }
    }

    spec fn div_ok(x: i64, b: i64) -> bool {
        x % b == 0
    }

    spec fn divides_gap(a: i64, b: i64, r: i64) -> bool {
        (a - r) % b == 0
    }

    spec fn divisor_nonzero(b: i64) -> bool {
        b != 0
    }

    spec fn divisor_ok(b: i64) -> bool {
        b != 0 && b != -1
    }

    spec fn is_floor_mod(a: i64, b: i64, r: i64) -> bool {
        (r == 0 || r > 0 && b > 0 || r < 0 && b < 0) && (if r < 0 { 0 - r } else { r }) < (if b < 0 { 0 - b } else { b }) && (a - r) % b == 0
    }

    #[effects(pure)]
    #[uses(abs_of, divides_gap, divisor_nonzero, sign_ok, small_ok)]
    fn mod_floor(a: i64, b: i64) -> (r: i64)
        requires divisor_nonzero(b),
        ensures sign_ok(b, r), small_ok(b, r), divides_gap(a, b, r),
    {
        if b == -1 {
            0
        } else {
            let m: i64 = a % b;
            if m != 0 && (m < 0) != (b < 0) {
                m + b
            } else {
                m
            }
        }
    }

    #[effects(pure)]
    #[uses(divides_gap, divisor_ok)]
    fn probe_adj(a: i64, b: i64) -> (r: i64)
        requires divisor_ok(b),
        ensures divides_gap(a, b, r),
    {
        let m: i64 = a % b;
        m + b
    }

    #[effects(pure)]
    #[uses(divisor_ok, same_mod, small_pair)]
    fn probe_same(x: i64, b: i64) -> (y: i64)
        requires divisor_ok(b), small_pair(x, b),
        ensures same_mod(x, y, b),
    {
        x - b
    }

    #[effects(pure)]
    #[uses(div_ok, divisor_ok, small_pair)]
    fn probe_shift(x: i64, b: i64) -> (y: i64)
        requires divisor_ok(b), small_pair(x, b), div_ok(x, b),
        ensures div_ok(y, b),
    {
        x - b
    }

    #[effects(pure)]
    #[uses(divides_gap, divisor_ok)]
    fn probe_trunc(a: i64, b: i64) -> (m: i64)
        requires divisor_ok(b),
        ensures divides_gap(a, b, m),
    {
        a % b
    }

    spec fn same_mod(x: i64, y: i64, b: i64) -> bool {
        x % b == y % b
    }

    spec fn sign_ok(b: i64, r: i64) -> bool {
        r == 0 || r > 0 && b > 0 || r < 0 && b < 0
    }

    spec fn small_ok(b: i64, r: i64) -> bool {
        abs_of(r) < abs_of(b)
    }

    spec fn small_pair(x: i64, b: i64) -> bool {
        x < 1000000000 && x > -1000000000 && b < 1000000000 && b > -1000000000
    }
}

#[summary("Maximum non-empty contiguous subarray sum (Kadane), proved optimal")]
mod tasks {
    spec fn is_max(a: &[i64], r: i64) -> bool {
        upper_bound(a, r) && (forall|t: i64| #[trigger] upper_bound(a, t) ==> r <= t)
    }

    #[effects(pure)]
    #[uses(is_max, seg, upper_bound, valid_input)]
    fn max_subarray(a: &[i64]) -> (r: i64)
        requires valid_input(a),
        ensures is_max(a, r),
    {
        let n: usize = a.len();
        let mut best: i64 = a[0];
        let mut bi: usize = 0;
        let mut bj: usize = 1;
        let mut cur: i64 = a[0];
        let mut ci: usize = 0;
        let mut k: usize = 1;
        while k < n
            invariant n == a.len(), n <= 1000000, 1 <= k, k <= n, bi < bj, bj <= k, best == seg(a, bi, bj), ci < k, cur == seg(a, ci, k), -1000000000 <= cur, cur <= 1000000000 * k, forall|i: usize, j: usize| i < j && j <= k ==> #[trigger] seg(a, i, j) <= best, forall|p: usize| p < k ==> #[trigger] seg(a, p, k) <= cur,
            decreases n - k,
        {
            let x: i64 = a[k];
            let ext: i64 = cur + x;
            if x > ext {
                cur = x;
                ci = k;
            } else {
                cur = ext;
            }
            if cur > best {
                best = cur;
                bi = ci;
                bj = k + 1;
            }
            k = k + 1;
        }
        best
    }

    spec fn seg(a: &[i64], i: usize, j: usize) -> i64
        decreases j,
    {
        if i >= j || j > a.len() {
            0
        } else {
            seg(a, i, j - 1) + a[j - 1]
        }
    }

    spec fn upper_bound(a: &[i64], t: i64) -> bool {
        forall|i: usize, j: usize| i < j && j <= a.len() ==> #[trigger] seg(a, i, j) <= t
    }

    spec fn valid_input(a: &[i64]) -> bool {
        1 <= a.len() && a.len() <= 1000000 && (forall|i: usize| i < a.len() ==> -1000000000 <= #[trigger] a[i] && #[trigger] a[i] <= 1000000000)
    }
}

#[summary("Second largest distinct value of an i64 slice (i64::MIN if fewer than two distinct values)")]
mod tasks {
    #[effects(pure)]
    #[uses(prefix_max_ok)]
    fn max_of(a: &[i64]) -> (mx: i64)
        ensures prefix_max_ok(a, a.len(), mx),
    {
        let mut cur: i64 = i64::MIN;
        let mut i: usize = 0;
        while i < a.len()
            invariant i <= a.len(), prefix_max_ok(a, i, cur),
            decreases a.len() - i,
        {
            if a[i] > cur {
                cur = a[i];
            }
            i = i + 1;
        }
        cur
    }

    spec fn partial_second_ok(a: &[i64], n: usize, m: i64, r: i64) -> bool {
        (forall|j: usize| j < n && j < a.len() && #[trigger] a[j] < m ==> a[j] <= r) && (r == i64::MIN || r < m && !(forall|k: usize| k < n && k < a.len() ==> #[trigger] a[k] != r))
    }

    spec fn prefix_max_ok(a: &[i64], n: usize, m: i64) -> bool {
        (forall|j: usize| j < n && j < a.len() ==> #[trigger] a[j] <= m) && (m == i64::MIN || !(forall|k: usize| k < n && k < a.len() ==> #[trigger] a[k] != m))
    }

    #[effects(pure)]
    #[uses(partial_second_ok)]
    fn second_below(a: &[i64], m: i64) -> (s: i64)
        ensures partial_second_ok(a, a.len(), m, s),
    {
        let mut best: i64 = i64::MIN;
        let mut i: usize = 0;
        while i < a.len()
            invariant i <= a.len(), partial_second_ok(a, i, m, best),
            decreases a.len() - i,
        {
            if a[i] < m && a[i] > best {
                best = a[i];
            }
            i = i + 1;
        }
        best
    }

    #[effects(pure)]
    #[uses(partial_second_ok, prefix_max_ok, second_spec)]
    fn second_max(a: &[i64]) -> (r: i64)
        ensures second_spec(a, r),
    {
        let m: i64 = max_of(a);
        second_below(a, m)
    }

    spec fn second_spec(a: &[i64], r: i64) -> bool {
        !(forall|m: i64| #[trigger] prefix_max_ok(a, a.len(), m) ==> !partial_second_ok(a, a.len(), m, r))
    }
}

#[summary("In-place rotation of an i64 slice to the right by k positions")]
mod tasks {
    spec fn both_in(a: &[i64], i: usize, j: usize) -> bool {
        i < a.len() && j < a.len()
    }

    #[effects(pure)]
    #[uses(both_in, reversed_range, src_index, swapped, valid_range)]
    fn reverse_range(a: &mut [i64], lo: usize, hi: usize) -> ()
        requires valid_range(a, lo, hi),
        ensures reversed_range(a, old(a), lo, hi),
        decreases hi - lo,
    {
        if hi - lo <= 1 {
            ()
        } else {
            swap_two(a, lo, hi - 1);
            reverse_range(a, lo + 1, hi - 1);
            ()
        }
    }

    spec fn reversed_range(a: &[i64], before: &[i64], lo: usize, hi: usize) -> bool {
        a.len() == before.len() && hi <= a.len() && (forall|p: usize| p < a.len() ==> #[trigger] a[p] == before[src_index(lo, hi, p)])
    }

    spec fn rot_src(n: usize, s: usize, p: usize) -> usize {
        if p >= s {
            p - s
        } else {
            p + n - s
        }
    }

    #[effects(pure)]
    #[uses(reversed_range, rot_src, rotated_right, src_index, valid_range)]
    fn rotate_right(a: &mut [i64], k: usize) -> ()
        ensures rotated_right(a, old(a), k),
    {
        let n: usize = a.len();
        if n == 0 {
            ()
        } else {
            let s: usize = k % n;
            reverse_range(a, 0, n);
            reverse_range(a, 0, s);
            reverse_range(a, s, n);
            ()
        }
    }

    spec fn rotated_right(a: &[i64], before: &[i64], k: usize) -> bool {
        a.len() == before.len() && (forall|p: usize| p < a.len() ==> #[trigger] a[p] == before[rot_src(a.len(), k % a.len(), p)])
    }

    spec fn src_index(lo: usize, hi: usize, p: usize) -> usize {
        if lo <= p && p < hi {
            lo + hi - 1 - p
        } else {
            p
        }
    }

    #[effects(pure)]
    #[uses(both_in, swapped)]
    fn swap_two(a: &mut [i64], i: usize, j: usize) -> ()
        requires both_in(a, i, j),
        ensures swapped(a, old(a), i, j),
    {
        let t: i64 = a[i];
        a[i] = a[j];
        a[j] = t;
        ()
    }

    spec fn swapped(a: &[i64], before: &[i64], i: usize, j: usize) -> bool {
        a.len() == before.len() && a[i] == before[j] && a[j] == before[i] && (forall|r: usize| r < a.len() && r != i && r != j ==> #[trigger] a[r] == before[r])
    }

    spec fn valid_range(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }
}

