#[summary("Integer square root task: isqrt(n) = largest r >= 0 with r*r <= n.")]
mod tasks {
    spec fn hi_bound(hi: i64) -> bool {
        0 < hi && hi <= 3037000500
    }

    spec fn in_domain(n: i64) -> bool {
        n >= 0
    }

    spec fn is_isqrt(n: i64, r: i64) -> bool {
        sq_le(n, r) && sq_gt(n, r + 1)
    }

    #[effects(pure)]
    #[uses(hi_bound, in_domain, is_isqrt, sq_gt, sq_le)]
    fn isqrt(n: i64) -> (r: i64)
        requires in_domain(n),
        ensures is_isqrt(n, r),
    {
        let mut lo: i64 = 0;
        let mut hi: i64 = 3037000500;
        while hi - lo > 1
            invariant hi_bound(hi), lo >= 0, lo < hi, sq_le(n, lo), sq_gt(n, hi),
            decreases hi - lo,
        {
            let mid: i64 = lo + (hi - lo) / 2;
            if mid * mid <= n {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        lo
    }

    spec fn sq_gt(n: i64, r: i64) -> bool {
        r * r > n
    }

    spec fn sq_le(n: i64, r: i64) -> bool {
        r >= 0 && r * r <= n
    }
}

